import React,{useState} from 'react';
type Proposal={title:string;fileId:string};
import {requiresReason} from './domain';
export function PlanningScreen({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){return <ProposalForm key={storeId} storeId={storeId} proposal={proposal} onSubmit={onSubmit}/>;}
function ProposalForm({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){
 const [form,setForm]=useState<Proposal>({title:'',fileId:''});
 const [status,setStatus]=useState<'NEW'|'IN_PROGRESS'|'POSTPONED'|'DONE'>('NEW');
 const [startedOn,setStartedOn]=useState<string|undefined>();
 const [reason,setReason]=useState('');
 const stop={id:'form',position:0,status,startedOn};
 return <form onSubmit={e=>{e.preventDefault();onSubmit({storeId,...form,status,...(startedOn?{startedOn}:{}),...(requiresReason(stop)?{reason}:{})});}}>
  <label>Title<input aria-label="Title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label>
  <label>File ID<input aria-label="File ID" value={form.fileId} onChange={e=>setForm({...form,fileId:e.target.value})}/></label>
  <button type="button" onClick={()=>proposal&&setForm({...proposal})}>Use upload</button>
  <label>Status<select aria-label="Status" value={status} onChange={e=>{const value=e.target.value as typeof status;setStatus(value);if(value==='IN_PROGRESS'&&!startedOn)setStartedOn(new Date().toISOString());}}><option value="NEW">New</option><option value="IN_PROGRESS">In progress</option><option value="POSTPONED">Postponed</option><option value="DONE">Done</option></select></label>
  {requiresReason(stop)&&<label>Reason<textarea aria-label="Reason" value={reason} required onChange={e=>setReason(e.target.value)}/></label>}
  <button type="submit">Save</button>
 </form>;
}

