import type {Stop} from './domain';
export function moveUp(stops:Stop[],activeIndex:number){
  const active=stops.filter(stop=>!stop.removed);
  const stop=active[activeIndex];
  if(!stop||activeIndex<=0)return undefined;
  // The API consumes a 1-based rank in the active list, not persisted positions.
  return {id:stop.id,position:activeIndex};
}
export {requiresReason as screenRequiresReason} from './domain';
export function fitsWindow(at:number,notice:{sentAt:number},appointments:{at:number;status:string}[],now:number){
  const next=appointments
    .filter(a=>a.at>now&&a.status!=='CANCELLED'&&a.status!=='HELD')
    .sort((a,b)=>a.at-b.at)[0];
  return at>=notice.sentAt&&Boolean(next&&at<next.at);
}

