import {test,expect} from 'bun:test';
import {fitsWindow,moveUp,screenRequiresReason} from './logic';
import {requiresReason} from './domain';
import type {Stop} from './domain';

const notice={sentAt:10};
const appointments=[{at:20,status:'PLANNED'},{at:17,status:'HELD'},{at:18,status:'CANCELLED'}];
test('scheduling includes the lower bound and excludes the next appointment bound',()=>{
 expect(fitsWindow(10,notice,appointments,10)).toBe(true);
 expect(fitsWindow(9,notice,appointments,10)).toBe(false);
 expect(fitsWindow(19,notice,appointments,10)).toBe(true);
 expect(fitsWindow(20,notice,appointments,10)).toBe(false);
});
test('move uses active rank even when stored positions have gaps',()=>{
 const stops=[{id:'a',position:0,status:'NEW'},{id:'removed',position:1,status:'NEW',removed:true},{id:'c',position:2,status:'NEW'}] as Stop[];
 expect(moveUp(stops,1)).toEqual({id:'c',position:1});
});
test('server and screen share reason behavior across started, postponed, and done states',()=>{
 const stop=(status:Stop['status'],startedOn?:string)=>({id:'x',position:0,status,startedOn} as Stop);
 for(const state of [stop('IN_PROGRESS','today'),stop('POSTPONED','today')]){
  expect(requiresReason(state)).toBe(true); expect(screenRequiresReason(state)).toBe(true);
 }
 for(const state of [stop('NEW'),stop('DONE','today'),stop('POSTPONED')]){
  expect(requiresReason(state)).toBe(false); expect(screenRequiresReason(state)).toBe(false);
 }
});
